import os
needles=('intercept-github-fetch.sh','0cc1c73a5e96749ab32d7ea5e14892fafa6972ae')
for root in ['/work','/tmp','/home','/opt','/usr/local','/app','/workspace','/root']:
    if not os.path.exists(root): continue
    print('SCAN',root)
    for base, dirs, files in os.walk(root, onerror=lambda e: None):
        # prune bulky ordinary installations
        if base.startswith('/usr/local/lib/python'): dirs[:] = []
        for f in files:
            p=os.path.join(base,f)
            if f in needles or 'intercept-github' in f or f == 'README.md': print(p)
